def _lane_lock(room, agent):
    """Exclusive flock per (room, agent), held from counting the lane's acts until sbd send has
    returned, so concurrent posts of one lane cannot both pass the ceiling. The lock files live
    beside the switchboard runtime, never inside it."""
    top = os.path.join(os.path.dirname(base_dir()), "osb-lane-locks")
    try:
        os.mkdir(top, 0o700)
    except FileExistsError:
        pass
    st = os.lstat(top)
    if not stat.S_ISDIR(st.st_mode) or st.st_uid != os.getuid() or st.st_mode & 0o022:
        raise Refused("lane policy: %s must be a private directory owned by this user" % top)
    fd = os.open(os.path.join(top, "%s@%s.lock" % (room, agent)),
                 os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
    except BaseException:
        os.close(fd)
        raise
    return fd


